// Auto Glance: blend photo into hero using a radial alpha mask (photo itself fades out)
const B64 = "";
(async () => {
  const hero = await figma.getNodeByIdAsync('1:53');
  const card = await figma.getNodeByIdAsync('1:80');
  if (!hero || !card) { figma.closePlugin('Hero not found'); return; }
  for (const n of hero.children.filter(c => /^Hero Banner/.test(c.name))) n.remove();

  const W = 1000, H = 667;           // 3:2 like the photo
  const holder = figma.createFrame();
  holder.name = 'Hero Banner Photo Blend';
  holder.fills = []; holder.clipsContent = false;
  holder.resize(W, H);
  hero.insertChild(2, holder);
  holder.layoutPositioning = 'ABSOLUTE';
  holder.x = hero.width - W + 150;   // extends past the right edge (clipped by hero)
  holder.y = (hero.height - H) / 2;

  const mask = figma.createRectangle();
  mask.name = 'Fade Mask';
  mask.resize(W, H);
  mask.fills = [{ type: 'GRADIENT_RADIAL', gradientTransform: [[1,0,0],[0,1,0]],
    gradientStops: [
      { position: 0,    color: { r:1, g:1, b:1, a: 1 } },
      { position: 0.5,  color: { r:1, g:1, b:1, a: 1 } },
      { position: 0.78, color: { r:1, g:1, b:1, a: 0.45 } },
      { position: 1,    color: { r:1, g:1, b:1, a: 0 } } ] }];
  holder.appendChild(mask);
  mask.x = 0; mask.y = 0;

  const img = figma.createImage(figma.base64Decode(B64));
  const photo = figma.createRectangle();
  photo.name = 'Photo';
  photo.resize(W, H);
  photo.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FILL' }];
  holder.appendChild(photo);
  photo.x = 0; photo.y = 0;

  holder.insertChild(0, mask);       // mask must be the bottom layer
  mask.isMask = true;
  try { mask.maskType = 'ALPHA'; } catch (e) {}

  card.fills = []; card.strokes = []; card.effects = [];
  for (const n of card.children) {
    if (/^Hero Photo|^Card Glow|Car Wash Illustration/.test(n.name)) n.visible = false;
  }
  figma.closePlugin('Done: radial-masked photo, maskType=' + mask.maskType + ', holder kids=' + holder.children.length);
})();
